/* @lc app=leetcode id=2835 lang=kotlin */ class Solution { fun sp(c: IntArray, b: Int, j: Int) = (j downTo b + 1).forEach { t -> c.set(t, c[t] - 1).also { c[t - 1] += 2 } } fun minOperations(nums: List<Int>, target: Int): Int = if (nums.sumOf { it.toLong() } < target) -1 else IntArray(34).also { c -> nums.forEach { c[Integer.numberOfTrailingZeros(it)]++ } }.let { c -> (0..31).fold(0) { ops, b -> (if (target shr b and 1 == 0 || c[b] > 0) 0 else (b + 1..33).first { c[it] > 0 }.let { j -> sp(c, b, j).let { j - b } }).also { if (target shr b and 1 == 1) c[b]-- }.also { c[b + 1] += c[b] / 2 }.let { ops + it } } } }